                .setKey("status").setSortProperty("status");
        grid.setSizeFull();

        grid.setItems(
                query -> customerService
                        .list(query.getOffset(), query.getLimit(), toSorts(query.getSortOrders()))
                        .stream(),
                query -> customerService.count());
    }

