+package com.example.customers;
+
+import com.example.customers.domain.*;
+import org.junit.jupiter.api.Test;
+
+import java.util.List;
+import java.util.Set;
+
+import static org.junit.jupiter.api.Assertions.*;
+
+class CustomerRepositoryTest {
+    @Test
+    void filteredPagesAreSortedAndEveryQueryIsRecorded() {
+        QueryLog log = new QueryLog();
+        CustomerRepository repository = new CustomerRepository(log);
+        CustomerFilter filter = new CustomerFilter("makinen", Set.of(CustomerStatus.ACTIVE));
+        int count = repository.count(filter);
+        List<CustomerSort> sort = List.of(new CustomerSort("firstName", false));
+        List<Customer> first = repository.findAll(0, 2, sort, filter);
+        List<Customer> next = repository.findAll(2, 2, sort, filter);
+        assertTrue(count > 2);
+        assertEquals(2, first.size());
+        assertEquals(2, next.size());
+        assertTrue(first.stream().allMatch(c -> c.status() == CustomerStatus.ACTIVE));
+        assertTrue(first.get(0).firstName().compareToIgnoreCase(first.get(1).firstName()) >= 0);
+        assertTrue(first.get(1).firstName().compareToIgnoreCase(next.get(0).firstName()) >= 0);
+        assertTrue(first.stream().noneMatch(next::contains));
+        assertEquals(List.of(count), log.countQueries());
+        assertEquals(List.of(new QueryLog.PageQuery(0, 2, 2), new QueryLog.PageQuery(2, 2, 2)),
+                log.pageQueries());
+        assertThrows(IllegalArgumentException.class,
+                () -> repository.findAll(0, 201, sort, filter));
+    }
+}
